CREATE TABLE facility_employee ( id uuid PRIMARY KEY, household_id uuid NOT NULL REFERENCES household(roster_id), hamlet_id bigint NOT NULL REFERENCES hamlet(id), resident_id uuid REFERENCES resident(roster_id), full_name varchar(255) NOT NULL, birth_year integer CHECK (birth_year IS NULL OR birth_year BETWEEN 1900 AND 2100), gender varchar(10) CHECK (gender IS NULL OR gender IN ('MALE','FEMALE','OTHER')), identity_ciphertext text, identity_lookup varchar(128), phone varchar(30) NOT NULL DEFAULT '', position varchar(200) NOT NULL DEFAULT '', home_address varchar(500) NOT NULL DEFAULT '', started_on date, ended_on date, notes varchar(2000) NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), created_by varchar(255) NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), updated_by varchar(255) NOT NULL, CONSTRAINT ck_facility_employee_period CHECK (ended_on IS NULL OR started_on IS NULL OR ended_on >= started_on), CONSTRAINT ck_facility_employee_identity CHECK ((identity_ciphertext IS NULL) = (identity_lookup IS NULL)) ); CREATE INDEX ix_facility_employee_household ON facility_employee(household_id, ended_on NULLS FIRST); CREATE INDEX ix_facility_employee_lookup ON facility_employee(identity_lookup) WHERE identity_lookup IS NOT NULL; COMMENT ON TABLE facility_employee IS 'Employees of an establishment; identity number encrypted';
CREATE TABLE facility_violation ( id uuid PRIMARY KEY, household_id uuid NOT NULL REFERENCES household(roster_id), hamlet_id bigint NOT NULL REFERENCES hamlet(id), occurred_on date, content varchar(1000) NOT NULL, decision_no varchar(100) NOT NULL DEFAULT '', authority varchar(200) NOT NULL DEFAULT '', penalty varchar(1000) NOT NULL DEFAULT '', notes varchar(2000) NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), created_by varchar(255) NOT NULL ); CREATE INDEX ix_facility_violation_household ON facility_violation(household_id, occurred_on DESC NULLS LAST); COMMENT ON TABLE facility_violation IS 'Violation history of an establishment';
ALTER TABLE attachment DROP CONSTRAINT attachment_owner_kind_check; ALTER TABLE attachment ADD CONSTRAINT attachment_owner_kind_check CHECK (owner_kind IN ('RESIDENT','FACILITY'));

DO $$ BEGIN
            IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='police_runtime') THEN
                GRANT SELECT,INSERT,UPDATE ON facility_employee TO police_runtime;
                GRANT SELECT,INSERT ON facility_violation TO police_runtime;
            END IF;
        END $$;

